/* Stage 2A room 2 (real Mednafen .mc1 save-state BAT/VRAM/CRAM)
 *
 * Generated by tools/pack_state_window.py:
 *   stage2a2_state_maps.bin : 4 screens x 32x24 plane A entries
 *   stage2a2_state_tiles.bin: 144 distinct 8x8 tiles converted to MD format
 *   stage2a2_state_pal.bin  : 4 MD palettes (top-used PCE palettes)
 *   player_spr.bin          : engine player test art
 */

.section .rodata
#include <macros.s>

GLABEL res_stage2a2_state_tiles
.incbin "../res/gfx/stage2a2_state_tiles.bin"
.align 2

GLABEL res_stage2a2_state_pal
.byte 0
.byte 63
.incbin "../res/gfx/stage2a2_state_pal.bin"
.align 2

GLABEL res_stage2a2_state_maps
.incbin "../res/gfx/stage2a2_state_maps.bin"
.align 2

GLABEL res_player_spr
.incbin "../res/gfx/player_spr.bin"
.align 2
